import React, { useState, useRef, useEffect } from 'react';
import {
  MessageCircle, Send, Paperclip, Smile, Mic, X,
  Search, Filter, MoreVertical, Phone, Video, Star,
  Check, CheckCheck, Clock, User, Shield, Pin,
  Image, File, Download, Trash2, Copy, Eye,
  ChevronRight, VolumeX, Maximize2, Minimize2,
  ArrowLeft, Calendar, Clock as ClockIcon, Hash,
  Users, Shield as ShieldIcon, Loader2
} from 'lucide-react';
import axios from 'axios';

const Messages = ({ currentUser }) => {
  const [activeChat, setActiveChat] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [inputMessage, setInputMessage] = useState('');
  const [notifications, setNotifications] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [conversations, setConversations] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [adminUsers, setAdminUsers] = useState([]);
  const [isSending, setIsSending] = useState(false);

  const messagesEndRef = useRef(null);
  const fileInputRef = useRef(null);

  // Charger les conversations au montage
  useEffect(() => {
    if (currentUser) {
      fetchConversations();
      fetchAdmins();
    }
  }, [currentUser]);

  // Récupérer les administrateurs
  const fetchAdmins = async () => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get('/api/users/admins', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setAdminUsers(response.data);
    } catch (error) {
      console.error('Erreur récupération admins:', error);
    }
  };

  // Récupérer les conversations
  const fetchConversations = async () => {
    try {
      setIsLoading(true);
      const token = localStorage.getItem('authToken');
      const response = await axios.get('/api/conversations', {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      // Formater les conversations
      const formattedConversations = response.data.map(conv => ({
        id: conv.id,
        name: conv.admin_name || `Admin ${conv.admin_id}`,
        avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${conv.admin_id}`,
        status: 'online', // À remplacer par un système réel
        lastMessage: conv.last_message || 'Aucun message',
        time: formatTime(conv.last_message_time || conv.updated_at),
        unread: conv.unread_count > 0,
        pinned: conv.is_pinned || false,
        admin_id: conv.admin_id,
        conversationData: conv
      }));

      setConversations(formattedConversations);

      // Si une conversation est active, recharger ses messages
      if (activeChat) {
        fetchMessages(activeChat);
      }
    } catch (error) {
      console.error('Erreur récupération conversations:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Récupérer les messages d'une conversation
  const fetchMessages = async (conversationId) => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get(`/api/conversations/${conversationId}/messages`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      // Mettre à jour les messages dans la conversation
      setConversations(prev => prev.map(conv => {
        if (conv.id === conversationId) {
          return {
            ...conv,
            messages: response.data.map(msg => ({
              id: msg.id,
              text: msg.content,
              time: new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
              sender: msg.sender_id === currentUser.id ? 'me' : 'them',
              status: msg.is_read ? 'read' : 'sent',
              file_url: msg.file_url,
              file_name: msg.file_name
            }))
          };
        }
        return conv;
      }));

      // Marquer comme lu
      markAsRead(conversationId);
    } catch (error) {
      console.error('Erreur récupération messages:', error);
    }
  };

  // Formater le temps
  const formatTime = (timestamp) => {
    if (!timestamp) return 'Jamais';

    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMins < 1) return 'À l\'instant';
    if (diffMins < 60) return `Il y a ${diffMins} min`;
    if (diffHours < 24) return `Il y a ${diffHours} h`;
    if (diffDays === 1) return 'Hier';
    if (diffDays < 7) return `Il y a ${diffDays} j`;
    return date.toLocaleDateString();
  };

  // Filtrage des conversations
  const filteredConversations = conversations.filter(conv =>
    conv.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    conv.lastMessage.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Conversation active
  const activeConversation = conversations.find(conv => conv.id === activeChat);

  // Auto-scroll
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (activeConversation?.messages) {
      setTimeout(() => {
        scrollToBottom();
      }, 100);
    }
  }, [activeConversation?.messages]);

  // Créer une nouvelle conversation
  const createNewConversation = async (adminId) => {
    try {
      setIsLoading(true);
      const token = localStorage.getItem('authToken');

      const response = await axios.post('/api/conversations', {
        admin_id: adminId,
        title: `Support - ${currentUser.email}`,
        user_id: currentUser.id
      }, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      setActiveChat(response.data.id);
      await fetchConversations(); // Recharger les conversations
    } catch (error) {
      console.error('Erreur création conversation:', error);
      alert('Erreur lors de la création de la conversation');
    } finally {
      setIsLoading(false);
    }
  };

  // Envoyer un message
  const handleSendMessage = async () => {
    if (!inputMessage.trim() || !activeConversation || isSending) return;

    try {
      setIsSending(true);
      const token = localStorage.getItem('authToken');

      // Envoyer le message
      const response = await axios.post(`/api/conversations/${activeChat}/messages`, {
        content: inputMessage.trim(),
        sender_id: currentUser.id
      }, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      // Mettre à jour localement
      const newMessage = {
        id: response.data.id,
        text: inputMessage.trim(),
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        sender: 'me',
        status: 'sent'
      };

      // Mettre à jour la conversation dans la liste
      setConversations(prev => prev.map(conv => {
        if (conv.id === activeChat) {
          const updatedMessages = [...(conv.messages || []), newMessage];
          return {
            ...conv,
            lastMessage: inputMessage.trim(),
            time: 'À l\'instant',
            messages: updatedMessages
          };
        }
        return conv;
      }));

      setInputMessage('');

      // Marquer comme lu
      await axios.put(`/api/conversations/${activeChat}/read`, {}, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

    } catch (error) {
      console.error('Erreur envoi message:', error);
      alert('Erreur lors de l\'envoi du message');
    } finally {
      setIsSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  // Marquer comme lu
  const markAsRead = async (conversationId) => {
    try {
      const token = localStorage.getItem('authToken');
      await axios.put(`/api/conversations/${conversationId}/read`, {}, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      // Mettre à jour localement
      setConversations(prev => prev.map(conv => 
        conv.id === conversationId ? { ...conv, unread: false } : conv
      ));

      // Mettre à jour les notifications
      updateNotifications();
    } catch (error) {
      console.error('Erreur marquage comme lu:', error);
    }
  };

  // Mettre à jour les notifications
  const updateNotifications = async () => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get('/api/conversations/unread-count', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setNotifications(response.data.count || 0);
    } catch (error) {
      console.error('Erreur mise à jour notifications:', error);
    }
  };

  // Épingler/désépingler
  const togglePin = async (conversationId) => {
    try {
      const conversation = conversations.find(c => c.id === conversationId);
      const token = localStorage.getItem('token');

      await axios.put(`/api/conversations/${conversationId}/pin`, {
        is_pinned: !conversation.pinned
      }, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      // Mettre à jour localement
      setConversations(prev => prev.map(conv => 
        conv.id === conversationId ? { ...conv, pinned: !conv.pinned } : conv
      ));
    } catch (error) {
      console.error('Erreur changement épingle:', error);
    }
  };

  // Toggle fullscreen
  const toggleFullscreen = () => {
    setIsFullscreen(!isFullscreen);
  };

  // Obtenir l'icône de statut
  const getStatusIcon = (status) => {
    switch (status) {
      case 'online': return <div className="h-2 w-2 rounded-full bg-green-500"></div>;
      case 'offline': return <div className="h-2 w-2 rounded-full bg-neutral-400"></div>;
      case 'away': return <div className="h-2 w-2 rounded-full bg-amber-500"></div>;
      default: return <div className="h-2 w-2 rounded-full bg-green-500"></div>;
    }
  };

  return (
    <div className={`bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 overflow-hidden ${isFullscreen ? 'fixed inset-4 z-50' : 'h-[600px]'}`}>
      <div className="flex h-full">

        {/* Sidebar des conversations */}
        <div className={`w-full md:w-80 lg:w-96 border-r border-neutral-200 dark:border-neutral-800 flex flex-col ${activeChat ? 'hidden md:flex' : 'flex'}`}>

          {/* Header Sidebar */}
          <div className="p-4 border-b border-neutral-200 dark:border-neutral-800">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-neutral-900 dark:text-white">Messages</h2>
              <div className="flex items-center space-x-2">
                {notifications > 0 && (
                  <span className="px-2 py-1 text-xs bg-red-500 text-white rounded-full">
                    {notifications}
                  </span>
                )}
                <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                  <MoreVertical className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                </button>
              </div>
            </div>

            {/* Barre de recherche */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-neutral-400" />
              <input
                type="text"
                placeholder="Rechercher des conversations..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500"
              />
            </div>

            {/* Filtres */}
            <div className="flex space-x-2 mt-3">
              <button className="px-3 py-1.5 text-sm bg-primary-500 text-white rounded-xl">
                Tous
              </button>
              <button className="px-3 py-1.5 text-sm bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 rounded-xl hover:bg-neutral-200 dark:hover:bg-neutral-700">
                Non lus
              </button>
              <button className="px-3 py-1.5 text-sm bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 rounded-xl hover:bg-neutral-200 dark:hover:bg-neutral-700">
                Épinglés
              </button>
            </div>
          </div>

          {/* Liste des conversations */}
          <div className="flex-1 overflow-y-auto">
            {isLoading ? (
              <div className="flex items-center justify-center h-full">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
              </div>
            ) : filteredConversations.length > 0 ? (
              filteredConversations.map((conversation) => (
                <div
                  key={conversation.id}
                  onClick={() => {
                    setActiveChat(conversation.id);
                    if (!conversation.messages) {
                      fetchMessages(conversation.id);
                    }
                    if (conversation.unread) {
                      markAsRead(conversation.id);
                    }
                  }}
                  className={`p-4 border-b border-neutral-100 dark:border-neutral-800/50 hover:bg-neutral-50 dark:hover:bg-neutral-800/30 cursor-pointer transition-colors ${activeChat === conversation.id ? 'bg-primary-50 dark:bg-primary-900/10' : ''} ${conversation.unread ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}
                >
                  <div className="flex items-center space-x-3">
                    <div className="relative">
                      <img
                        src={conversation.avatar}
                        alt={conversation.name}
                        className="h-12 w-12 rounded-xl"
                      />
                      <div className="absolute -bottom-1 -right-1">
                        {getStatusIcon(conversation.status)}
                      </div>
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between mb-1">
                        <h3 className="font-semibold text-neutral-900 dark:text-white truncate">
                          {conversation.name}
                        </h3>
                        <div className="flex items-center space-x-2">
                          {conversation.pinned && (
                            <Pin className="h-3 w-3 text-amber-500" />
                          )}
                          <span className="text-xs text-neutral-500 dark:text-neutral-500">
                            {conversation.time}
                          </span>
                        </div>
                      </div>

                      <p className="text-sm text-neutral-600 dark:text-neutral-400 truncate">
                        {conversation.lastMessage}
                      </p>

                      <div className="flex items-center justify-between mt-2">
                        <div className="flex items-center space-x-2">
                          {conversation.unread && (
                            <div className="h-2 w-2 bg-primary-500 rounded-full animate-pulse"></div>
                          )}
                          <span className="text-xs text-neutral-500 dark:text-neutral-500">
                            {conversation.unread ? 'Nouveau' : 'Vu'}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-8 text-center">
                <MessageCircle className="h-12 w-12 text-neutral-400 mx-auto mb-4" />
                <p className="text-neutral-600 dark:text-neutral-400 mb-4">
                  Aucune conversation
                </p>
                {adminUsers.length > 0 && (
                  <button
                    onClick={() => createNewConversation(adminUsers[0].id)}
                    className="px-4 py-2 text-sm bg-primary-500 text-white rounded-xl hover:bg-primary-600 transition-colors"
                  >
                    Démarrer une conversation
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Zone de chat principale */}
        <div className={`flex-1 flex flex-col ${activeChat ? 'flex' : 'hidden md:flex'}`}>

          {/* Header Chat */}
          {activeConversation ? (
            <>
              <div className="p-4 border-b border-neutral-200 dark:border-neutral-800 flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <button
                    onClick={() => setActiveChat(null)}
                    className="md:hidden p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl"
                  >
                    <ArrowLeft className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <div className="relative">
                    <img
                      src={activeConversation.avatar}
                      alt={activeConversation.name}
                      className="h-10 w-10 rounded-xl"
                    />
                    <div className="absolute -bottom-1 -right-1">
                      {getStatusIcon(activeConversation.status)}
                    </div>
                  </div>
                  <div>
                    <h3 className="font-bold text-neutral-900 dark:text-white">
                      {activeConversation.name}
                    </h3>
                    <div className="flex items-center space-x-2">
                      <span className="text-xs text-neutral-600 dark:text-neutral-400">
                        Support Administratif
                      </span>
                      <span className="text-xs text-neutral-500 dark:text-neutral-500">•</span>
                      <span className="text-xs text-neutral-600 dark:text-neutral-400">
                        {activeConversation.time}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <button 
                    onClick={() => togglePin(activeChat)}
                    className={`p-2 rounded-xl ${activeConversation.pinned ? 'bg-amber-500/10 text-amber-500' : 'hover:bg-neutral-100 dark:hover:bg-neutral-800'}`}
                  >
                    <Pin className="h-5 w-5" />
                  </button>
                  <button 
                    onClick={toggleFullscreen}
                    className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl"
                  >
                    {isFullscreen ? (
                      <Minimize2 className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                    ) : (
                      <Maximize2 className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                    )}
                  </button>
                  <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl">
                    <MoreVertical className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                </div>
              </div>

              {/* Zone des messages */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-thin scrollbar-thumb-neutral-300 dark:scrollbar-thumb-neutral-700">
                {activeConversation.messages && activeConversation.messages.length > 0 ? (
                  <>
                    <div className="text-center">
                      <span className="px-3 py-1 text-xs bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 rounded-full">
                        Conversation avec le support
                      </span>
                    </div>

                    {activeConversation.messages.map((message) => (
                      <div
                        key={message.id}
                        className={`flex ${message.sender === 'me' ? 'justify-end' : 'justify-start'}`}
                      >
                        <div className={`max-w-[70%] rounded-2xl p-4 ${message.sender === 'me'
                          ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                          : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                        }`}>
                          <p className="text-sm">{message.text}</p>
                          {message.file_url && (
                            <div className="mt-2">
                              <a 
                                href={message.file_url} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center space-x-2 text-sm text-blue-500 hover:text-blue-600"
                              >
                                <File className="h-4 w-4" />
                                <span>{message.file_name || 'Fichier joint'}</span>
                              </a>
                            </div>
                          )}
                          <div className={`flex items-center justify-between mt-3 ${message.sender === 'me' ? 'text-white/80' : 'text-neutral-500'}`}>
                            <span className="text-xs">{message.time}</span>
                            {message.sender === 'me' && (
                              <div className="flex items-center space-x-1">
                                {message.status === 'sent' && <Check className="h-3 w-3" />}
                                {message.status === 'delivered' && <CheckCheck className="h-3 w-3" />}
                                {message.status === 'read' && <CheckCheck className="h-3 w-3 text-blue-400" />}
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </>
                ) : (
                  <div className="flex items-center justify-center h-full">
                    <div className="text-center">
                      <MessageCircle className="h-12 w-12 text-neutral-400 mx-auto mb-4" />
                      <p className="text-neutral-600 dark:text-neutral-400">
                        Aucun message dans cette conversation
                      </p>
                      <p className="text-sm text-neutral-500 mt-2">
                        Commencez la discussion avec le support
                      </p>
                    </div>
                  </div>
                )}

                <div ref={messagesEndRef} />
              </div>

              {/* Zone de saisie */}
              <div className="p-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="flex items-center space-x-3">
                  <input
                    type="file"
                    ref={fileInputRef}
                    className="hidden"
                    onChange={async (e) => {
                      const file = e.target.files[0];
                      if (file) {
                        // TODO: Implémenter l'upload de fichier
                        console.log('Fichier sélectionné:', file);
                      }
                    }}
                  />
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl"
                  >
                    <Paperclip className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                  </button>
                  <div className="flex-1 relative">
                    <input
                      type="text"
                      value={inputMessage}
                      onChange={(e) => setInputMessage(e.target.value)}
                      onKeyPress={handleKeyPress}
                      placeholder="Écrivez votre message..."
                      disabled={isSending}
                      className="w-full pl-4 pr-12 py-3 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
                    />
                    <button className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg">
                      <Smile className="h-4 w-4 text-neutral-600 dark:text-neutral-400" />
                    </button>
                  </div>
                  <button
                    onClick={handleSendMessage}
                    disabled={!inputMessage.trim() || isSending}
                    className={`p-3 rounded-xl transition-all duration-300 flex items-center justify-center ${inputMessage.trim() && !isSending
                      ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25'
                      : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-400 cursor-not-allowed'
                    }`}
                  >
                    {isSending ? (
                      <Loader2 className="h-5 w-5 animate-spin" />
                    ) : (
                      <Send className="h-5 w-5" />
                    )}
                  </button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-8">
              <div className="h-24 w-24 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center mb-6">
                <MessageCircle className="h-12 w-12 text-white" />
              </div>
              <h3 className="text-xl font-bold text-neutral-900 dark:text-white mb-2">
                Bienvenue dans Messages
              </h3>
              <p className="text-neutral-600 dark:text-neutral-400 text-center mb-6 max-w-md">
                Sélectionnez une conversation ou démarrez-en une nouvelle pour discuter avec notre équipe de support.
              </p>
              {adminUsers.length > 0 && (
                <button
                  onClick={() => createNewConversation(adminUsers[0].id)}
                  className="px-6 py-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-medium hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300"
                >
                  Nouvelle conversation
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Messages;
